import saved from "@/assets/sharedElfTreetopReferences.json";
import type { TilesetDef } from "../types";
import type { TilesetReferenceCategory } from "../tilesetReferences";

// Elf treetop village (tiledata/elf-treetop): one category on the bundled forest_harmony — build order, the place,
// its full layout and the treetop parts dictionary. Generated by scripts/content/prepare-elf-treetop-references.mjs.
const CATEGORY_BY_TILESET = saved as unknown as Record<string, TilesetReferenceCategory>;

/** Add the shipped category once to the bundled forest_harmony copy; authored or shared-from categories are left alone. */
export function ensureElfTreetopReferences(tileset: TilesetDef): boolean {
  const category = CATEGORY_BY_TILESET[tileset.id];
  if (!category || tileset.image.type !== "bundled" || tileset.image.id !== "tex_forest_harmony" || tileset.referenceSourceTilesetId) return false;
  if ((tileset.referenceDocuments ?? []).some(c => c.id === category.id)) return false;
  tileset.referenceDocuments = [...(tileset.referenceDocuments ?? []), structuredClone(category)];
  return true;
}
